// Stereo equal-power panning, matching Web Audio StereoPannerNode.
export function panMatrix(pan=0){pan=Math.max(-1,Math.min(1,Number(pan)||0));if(pan<=0){const a=(pan+1)*Math.PI/2;return [1,Math.cos(a),0,Math.sin(a)]}const a=pan*Math.PI/2;return [Math.cos(a),0,Math.sin(a),1]}
export function clickWave(rate=44100){const data=new Float32Array(Math.ceil(.035*rate));for(let i=0;i<data.length;i++){const t=i/rate;data[i]=Math.sin(2*Math.PI*1400*t)*Math.exp(-t*140)*Math.min(1,i/(rate*.001))*.7}return data}
export function makeGrid(duration,bpm,offset=0){bpm=Number(bpm);offset=Number(offset);if(!Number.isFinite(bpm)||bpm<30||bpm>300||!Number.isFinite(offset))throw Error('BPM deve estar entre 30 e 300; alinhamento deve ser um número.');const period=60/bpm,start=offset+Math.max(0,Math.ceil(-offset/period))*period,beats=[];for(let t=start;t<duration;t+=period)beats.push(t);return beats}
export function lowerBound(array,value){let a=0,b=array.length;while(a<b){const m=(a+b)>>>1;if(array[m]<value)a=m+1;else b=m}return a}
export function prepareMix(tracks,click=null,rate=44100){const sources=tracks.map(t=>({...t,matrix:panMatrix(t.pan)})),wave=clickWave(rate),matrix=panMatrix(click?.pan),beats=click?.enabled?click.beats:[];return {render(start,length,divisor=1){const left=new Float32Array(length),right=new Float32Array(length);for(const t of sources){const [a,b,c,d]=t.matrix;for(let j=0;j<length;j++){const l=t.left[start+j]||0,r=t.right[start+j]||0;left[j]+=(a*l+b*r)*t.gain;right[j]+=(c*l+d*r)*t.gain}}if(beats?.length){const from=lowerBound(beats,(start-wave.length)/rate);for(let k=from;k<beats.length;k++){const pos=Math.round(beats[k]*rate);if(pos>=start+length)break;const lo=Math.max(start,pos),hi=Math.min(start+length,pos+wave.length);for(let i=lo;i<hi;i++){const v=wave[i-pos]*(click.volume??.5);left[i-start]+=v*(matrix[0]+matrix[1]);right[i-start]+=v*(matrix[2]+matrix[3]);}}}if(divisor!==1)for(let i=0;i<length;i++){left[i]/=divisor;right[i]/=divisor}return {left,right}}}}
